const sha = (s: string) => createHash("sha256").update(s).digest("hex");
interface Execution {
  command: string[];
  request: string;
  requestSha256: string;
  reply: string;
  exitCode: number;
  events: Record<string, any>[];
  nativeTrace: Record<string, any>[];
