test("behavior families cover every actual coach/review/learning ID without a scenario Cartesian claim", () => {
  const cases = [
    ...createBehaviorPilotCases(),
    ...createBehaviorExpansionCases(),
  ];
  const ids = new Set(
    cases.flatMap((c) =>
