    });
}
let rows: CodexRow[] = expected
  .map((item) => latestCodexObservation(previous, item))
  .filter((row): row is CodexRow => !!row);
const archive = (): CodexArchive => ({
  method: "codex-cli-source-review",
  schemaVersion: 1,
  completedAt: new Date().toISOString(),
