test("Codex evidence rejects absent, incomplete, and API-disguised executions", () => {
  assert.ok(validateCodexArchive({}, []).issues.length);
  assert.ok(
    validateCodexArchive(
      { method: "live-openai-chat-completions", cases: [] },
