  if (!res.ok) throw Error(`Protocol ${method}: ${res.status}`);
  const result = res.headers.get("content-type")?.includes("text/event-stream")
    ? text
        .split("\n")
        .filter((l) => l.startsWith("data:"))
        .map((l) => JSON.parse(l.slice(5)))
        .find((p) => p.id === id)
    : JSON.parse(text);
