    if (page === "practice") {
      const scene = compatibleScenes(prompt).find(s => s.id === params.get("scene"));
      if (scene) route.sceneSelection = {
        sceneId: scene.id,
        pace: params.get("pace") === "mock" && prompt.id === "roleplay-coach" && scene.category === "interview" ? "mock" : "coached",
