}
button {
  border: 0;
  background: none;
  cursor: pointer;
}
a {
  color: inherit;
  text-decoration: none;
}
button,
input,
select,
summary {
  min-height: 44px;
}
button,
a,
summary,
dialog,
.app-header,
.section-label,
.view-caption,
.settings-signature {
  -webkit-user-select: none;
  user-select: none;
}
/* Keep native editing and intentional copying available. */
input,
textarea,
[contenteditable]:not([contenteditable="false"]),
.spoken-script {
  -webkit-user-select: text;
  user-select: text;
}
button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible,
summary:focus-visible,
.page-scroll:focus-visible {
