}
/* Restored focus must not leave keyboard rings after a tap or mouse click. */
:root[data-input-mode="pointer"]
  :is(
    button,
    a,
    summary,
    .page-scroll,
    input[type="radio"],
    input[type="checkbox"]
  ):focus,
:root[data-input-mode="pointer"] .language-options label:has(:focus-visible) {
