  const trigger = useRef<HTMLButtonElement>(null);
  const origin = useRef("");
  const [open, setOpen] = useState(false);
  useEffect(() => {
    const close = () => setOpen(false);
    window.addEventListener("hashchange", close);
    window.addEventListener("popstate", close);
    window.addEventListener("talksprout:navigate", close);
    return () => {
      window.removeEventListener("hashchange", close);
      window.removeEventListener("popstate", close);
      window.removeEventListener("talksprout:navigate", close);
    };
  }, []);
  function close() {
    writer.invalidate();
    setOpen(false);
    if (origin.current === location.href) trigger.current?.focus({ preventScroll: true });
  }
  return <>
    <button ref={trigger} type="button" className={placement === "header" ? "icon-button app-share-button" : "settings-row"}
      aria-label={placement === "header" ? s("分享应用", "Share app") : s("分享 TalkSprout", "Share TalkSprout")}
      title={s("分享 TalkSprout", "Share TalkSprout")} onClick={() => { origin.current = location.href; onMessage(""); setOpen(true); }}>
      {placement === "header" ? <Icon name="share" /> : <>
        <span className="entry-icon"><Icon name="share" /></span>
        <span className="row-text"><strong>{s("分享 TalkSprout", "Share TalkSprout")}</strong><small>{s("复制链接或生成二维码卡片", "Copy a link or create a QR card")}</small></span>
        <Icon name="chevron" />
      </>}
    </button>
    {open && <AppShareDialog locale={locale} writer={writer} copying={copying} onClose={close} />}
  </>;
}
"},{"path":"src/AppShareDialog.tsx","content":"import { useEffect, useId, useRef, useState } from "react";
import type { ClipboardWriter } from "./clipboard-writer";
import type { Locale } from "./types";
import type { ShareCardCopy } from "./share-card";
import { Icon } from "./Icon";

interface Card { src: string; file: File; copy: ShareCardCopy }
function fileShareSupported(file: File): boolean {
  try { return typeof navigator.canShare === "function" && navigator.canShare({ files: [file] }); }
  catch { return false; }
}

export function AppShareDialog({ locale, writer, copying, onClose }: {
  locale: Locale;
  writer: ClipboardWriter;
  copying: boolean;
  onClose: () => void;
}) {
  const s = (zh: string, en: string) => locale === "en" ? en : zh;
  const dialog = useRef<HTMLDialogElement>(null);
  const field = useRef<HTMLInputElement>(null);
  const alive = useRef(true);
  const pending = useRef(false);
  const [sharing, setSharing] = useState(false);
  const [feedback, setFeedback] = useState("");
  const [card, setCard] = useState<Card | null>(null);
  const [cardError, setCardError] = useState(false);
  const [attempt, setAttempt] = useState(0);
  const id = useId();
  const url = new URL("./", location.href).href;
  useEffect(() => {
    alive.current = true;
    const element = dialog.current!;
    element.showModal();
    return () => { alive.current = false; writer.invalidate(); element.close(); };
  }, [writer]);
  useEffect(() => {
    let disposed = false;
    let objectUrl: string | undefined;
    setCard(null);
    setCardError(false);
    setFeedback("");
    void import("./share-card").then(async module => {
      const blob = await module.renderShareCard(url, locale);
      if (disposed) return;
      objectUrl = URL.createObjectURL(blob);
      setCard({ src: objectUrl, file: new File([blob], `talksprout-share-${locale}.png`, { type: "image/png" }), copy: module.shareCardCopy[locale] });
    }).catch(() => { if (!disposed) setCardError(true); });
    return () => { disposed = true; if (objectUrl) URL.revokeObjectURL(objectUrl); };
  }, [url, locale, attempt]);

  function close() {
    dialog.current?.close();
    onClose();
  }
  function copy() {
    setFeedback("");
    void writer.write({ text: url,
      onSuccess: () => { if (alive.current) setFeedback(s("应用链接已复制，可以发给朋友。", "App link copied. Send it to a friend.")); },
      onFailure: () => {
        if (!alive.current) return;
        setFeedback(s("请选中并手动复制应用链接。", "Select and copy the app link manually."));
        field.current?.focus(); field.current?.select();
      },
    });
  }
  async function share(file?: File) {
    if (pending.current) return;
    pending.current = true;
    setSharing(true);
    setFeedback("");
    try {
      // Files are already generated, so the native call stays in the click gesture.
      await navigator.share(file ? { files: [file], title: "TalkSprout" } : {
        title: s("TalkSprout 开口芽", "TalkSprout"),
        text: s("用 TalkSprout 和 AI 开口练英语，每天进步一点。", "Practice speaking English with AI using TalkSprout, a little every day."),
        url,
      });
    } catch (error) {
      if (alive.current && !(error instanceof DOMException && error.name === "AbortError")) {
        setFeedback(file ? s("图片未能分享，请下载卡片后发送，或长按预览图查看存储选项。", "Could not share the image. Download the card to send it, or touch and hold its preview for save options.") : s("无法打开系统分享，请复制应用链接。", "Could not open system sharing. Copy the app link instead."));
      }
    } finally {
      pending.current = false;
      if (alive.current) setSharing(false);
    }
  }
  return <dialog ref={dialog} className="app-share-dialog" aria-labelledby={`${id}-title`} onCancel={event => { event.preventDefault(); close(); }}>
    <div className="app-share-heading"><div><span className="app-share-eyebrow">TalkSprout</span><h2 id={`${id}-title`}>{s("分享 TalkSprout", "Share TalkSprout")}</h2></div>
      <button type="button" className="icon-button" aria-label={s("关闭", "Close")} onClick={close}><Icon name="close" /></button></div>
    <p className="app-share-intro">{s("发一个链接，或把这张开口芽卡片送给朋友。", "Send a link, or pass this little invitation to a friend.")}</p>
    <div className="app-share-link-actions">
      {typeof navigator.share === "function" && <button type="button" className="app-share-primary" disabled={sharing} onClick={() => void share()}>{s("分享应用链接", "Share app link")}</button>}
      <button type="button" className="app-share-secondary" disabled={copying} onClick={copy}>{s("复制应用链接", "Copy app link")}</button>
    </div>
    <label className="app-share-link-label" htmlFor={`${id}-link`}>{s("应用首页链接", "App home link")}</label>
    <input ref={field} id={`${id}-link`} readOnly value={url} onFocus={event => event.currentTarget.select()} />
    <p className="app-share-feedback" role="status">{feedback}</p>
    <section className="app-share-card-section" aria-labelledby={`${id}-card-title`}>
      <h3 id={`${id}-card-title`}>{s("二维码分享卡片", "QR sharing card")}</h3>
      {!card && !cardError && <p role="status">{s("正在生成卡片…", "Creating your card…")}</p>}
      {cardError && <div className="app-share-card-error"><p role="status">{s("卡片暂未生成，你仍可复制链接分享。", "The card could not be created. You can still share the link.")}</p><button type="button" className="app-share-secondary" onClick={() => setAttempt(value => value + 1)}>{s("重新生成卡片", "Retry creating card")}</button></div>}
      {card && <>
        <div className="app-share-card-actions">
          {typeof navigator.share === "function" && fileShareSupported(card.file) && <button type="button" className="app-share-primary" disabled={sharing} onClick={() => void share(card.file)}>{s("分享卡片图片", "Share card image")}</button>}
          <a className="app-share-secondary" href={card.src} download={card.file.name}>{s("下载分享卡片", "Download share card")}</a>
        </div>
        <p className="app-share-save-hint">{s("iPhone：也可长按预览图，查看可用的存储选项。下载 PNG 不会自动加入「照片」。", "On iPhone, you can also touch and hold the preview for available save options. A PNG download is not automatically added to Photos.")}</p>
        <img className="app-share-preview" src={card.src} width="1080" height="1800" alt={s("TalkSprout 二维码分享卡片，包含应用首页网址和 iPhone 打开指引", "TalkSprout QR sharing card with the app home address and iPhone opening instructions")} />
        <details className="app-share-opening" open><summary>{card.copy.instructionsTitle}</summary>
          <dl><dt>{card.copy.otherScreen.title}</dt><dd>{card.copy.otherScreen.body}{card.copy.otherScreen.alternative && <span className="app-share-alternative">{card.copy.otherScreen.alternative}</span>}</dd><dt>{card.copy.samePhone.title}</dt><dd>{card.copy.samePhone.body}</dd></dl>
          <p>{card.copy.fallback}</p><a href={url}>{url}</a>
        </details>
      </>}
    </section>
  </dialog>;
}
"},{"path":"src/share-card.ts","content":"import QRCode from "qrcode";
import appIcon from "../public/icons/icon-192.png";
import type { Locale } from "./types";

interface OpeningInstruction { title: string; body: string; alternative?: string }
export interface ShareCardCopy {
  brand: string;
  headline: string[];
  description: string;
  scanLabel: string;
  instructionsTitle: string;
  otherScreen: OpeningInstruction;
  samePhone: OpeningInstruction;
  fallback: string;
  footer: string;
}
export const shareCardCopy: Record<Locale, ShareCardCopy> = {
  zh: {
    brand: "TalkSprout · 开口芽",
    headline: ["把英语，", "说进日常。"],
    description: "选好提示词，去常用 AI 开口练英语。",
    scanLabel: "扫码打开 TalkSprout",
    instructionsTitle: "iPhone 怎么打开",
    otherScreen: { title: "二维码在另一块屏幕上", body: "打开「相机」对准二维码，轻点出现的链接。", alternative: "也可用控制中心的「扫码器」。" },
    samePhone: { title: "图片就在这台 iPhone 上", body: "存到「照片」后打开，尝试长按二维码或网址，再打开链接。" },
    fallback: "没有识别出来？在 Safari 输入下方网址。",
    footer: "无需账号 · 搭配你常用的 AI 应用练习",
  },
  en: {
    brand: "TalkSprout",
    headline: ["A little English.", "A little every day."],
    description: "Choose a prompt. Start speaking with your AI.",
    scanLabel: "Scan to open TalkSprout",
    instructionsTitle: "Opening on iPhone",
    otherScreen: { title: "On another screen", body: "Open Camera, point it at the QR code, then tap the link.", alternative: "Or use Code Scanner in Control Center." },
    samePhone: { title: "Saved on this iPhone", body: "Save to Photos and open it. Try touching and holding the QR code or the address below, then choose an available open-link action." },
    fallback: "No link detected? Type the address below in Safari.",
    footer: "No account · Practise with the AI app you use",
  },
};

const colors = { background: "#f3f5f1", ink: "#223e34", green: "#285a46", muted: "#596d60", border: "#d6dfd3", white: "#ffffff" };
const font = 'system-ui, -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif';

/** A local, self-contained PNG. QR modules remain square with a four-module quiet zone. */
export async function renderShareCard(url: string, locale: Locale): Promise<Blob> {
  await document.fonts.ready;
  const copy = shareCardCopy[locale];
  const canvas = document.createElement("canvas");
  canvas.width = 1080;
  canvas.height = 1800;
  const context = canvas.getContext("2d");
  if (!context) throw new Error("Canvas unavailable");
  const ctx = context;
  const margin = 88;
  const contentWidth = canvas.width - margin * 2;
  ctx.fillStyle = colors.background;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.textBaseline = "top";

  function text(value: string, x: number, y: number, size: number, weight = 400, color = colors.ink) {
    ctx.font = `${weight} ${size}px ${font}`;
    ctx.fillStyle = color;
    ctx.fillText(value, x, y);
  }
  function wrapped(value: string, y: number, size: number, lineHeight: number, color = colors.ink, weight = 400): number {
    ctx.font = `${weight} ${size}px ${font}`;
    const units = locale === "en" ? value.split(/(?<=\s)/) : Array.from(value);
    let line = "";
    for (const unit of units) {
      if (line && ctx.measureText(line + unit).width > contentWidth) {
        text(line.trimEnd(), margin, y, size, weight, color);
        y += lineHeight;
        line = "";
      }
      line += unit;
    }
    if (line) { text(line.trimEnd(), margin, y, size, weight, color); y += lineHeight; }
    return y;
  }

  // The leaf mark continues the app's growing-sprout identity without obscuring the code.
  ctx.fillStyle = colors.green;
  ctx.beginPath();
  ctx.ellipse(105, 76, 19, 10, -Math.PI / 4, 0, Math.PI * 2);
  ctx.fill();
  text(copy.brand, 142, 60, 30, 650, colors.green);
  let y = 136;
  for (const line of copy.headline) { text(line, margin, y, locale === "en" ? 72 : 80, 750); y += 96; }
  y = wrapped(copy.description, y + 12, 32, 44, colors.muted) + 28;

  const matrix = QRCode.create(url, { errorCorrectionLevel: "H" }).modules;
  const moduleSize = Math.floor(560 / (matrix.size + 8));
  if (moduleSize < 2) throw new Error("App URL is too long for a readable card");
  const qrSize = (matrix.size + 8) * moduleSize;
  const qrX = Math.floor((canvas.width - qrSize) / 2);
  const qrY = Math.round(y);
  ctx.fillStyle = colors.white;
  ctx.fillRect(qrX, qrY, qrSize, qrSize);
  ctx.fillStyle = "#111111";
  for (let row = 0; row < matrix.size; row++) for (let column = 0; column < matrix.size; column++) {
    if (matrix.get(row, column)) ctx.fillRect(qrX + (column + 4) * moduleSize, qrY + (row + 4) * moduleSize, moduleSize, moduleSize);
  }
  // Reserve a small central badge; high error correction protects the covered modules.
  const icon = new Image();
  icon.src = appIcon;
  await icon.decode();
  const badgeSize = Math.floor(matrix.size * moduleSize * 0.18);
  const badgeX = Math.round(qrX + (qrSize - badgeSize) / 2);
  const badgeY = Math.round(qrY + (qrSize - badgeSize) / 2);
  ctx.fillStyle = colors.white;
  ctx.fillRect(badgeX - 6, badgeY - 6, badgeSize + 12, badgeSize + 12);
  ctx.drawImage(icon, badgeX, badgeY, badgeSize, badgeSize);
  y = qrY + qrSize + 28;
  ctx.font = `650 34px ${font}`;
  text(copy.scanLabel, (canvas.width - ctx.measureText(copy.scanLabel).width) / 2, y, 34, 650, colors.green);
  y += 74;
  ctx.fillStyle = colors.border;
  ctx.fillRect(margin, y, contentWidth, 2);
  y += 30;
  text(copy.instructionsTitle, margin, y, 34, 700);
  y += 60;
  for (const instruction of [copy.otherScreen, copy.samePhone]) {
    y = wrapped(instruction.title, y, 29, 40, colors.green, 650) + 10;
    y = wrapped(instruction.body, y, 28, 40, colors.ink);
    if (instruction.alternative) y = wrapped(instruction.alternative, y + 6, 26, 38, colors.muted);
    y += 24;
  }
  y = wrapped(copy.fallback, y, 28, 40, colors.muted) + 18;
  // Render every URL character, even at a narrow deployment path or with a long host.
  ctx.font = `26px ${font}`;
  let line = "";
  for (const character of url) {
    if (line && ctx.measureText(line + character).width > contentWidth) {
      text(line, margin, y, 26, 500, colors.green); y += 36; line = "";
    }
    line += character;
  }
  if (line) { text(line, margin, y, 26, 500, colors.green); y += 36; }
  y += 28;
  wrapped(copy.footer, y, 25, 36, colors.muted);
  if (y + 72 > canvas.height) throw new Error("Card text exceeds image bounds");
  return new Promise((resolve, reject) => canvas.toBlob(blob => blob ? resolve(blob) : reject(new Error("PNG export unavailable")), "image/png"));
}
"},{"path":"src/app-share.css","content":".app-share-button { flex-shrink: 0; }
.app-share-dialog {
  width: min(480px, calc(100vw - 24px));
  box-sizing: border-box;
  border: 1px solid var(--border);
  border-radius: 20px;
  --share-padding: 24px;
  padding: var(--share-padding);
  color: var(--ink);
  background: var(--canvas);
  max-height: calc(100dvh - 24px);
  overflow: auto;
  overscroll-behavior: contain;
}
.app-share-dialog::backdrop { background: rgb(20 35 28 / 40%); }
.app-share-heading { display: flex; align-items: center; gap: 12px; position: sticky; top: calc(-1 * var(--share-padding)); margin: calc(-1 * var(--share-padding)) calc(-1 * var(--share-padding)) 16px; padding: var(--share-padding); padding-bottom: 14px; background: var(--canvas); border-bottom: 1px solid var(--border); z-index: 1; }
.app-share-heading > div { flex: 1; min-width: 0; }
.app-share-heading h2 { margin: 4px 0 0; font-size: 21px; overflow-wrap: anywhere; }
.app-share-eyebrow { color: var(--green); font-size: 12px; font-weight: 650; }
.app-share-dialog p { color: var(--muted); line-height: 1.6; }
.app-share-intro { margin-bottom: 16px; }
.app-share-link-label { display: block; margin: 16px 0 8px; font-size: 13px; color: var(--muted); }
.app-share-dialog input { width: 100%; box-sizing: border-box; padding: 12px; font: inherit; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); }
.app-share-link-actions, .app-share-card-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.app-share-primary, .app-share-secondary { flex: 1 1 140px; display: flex; align-items: center; justify-content: center; text-align: center; min-height: 44px; padding: 11px 12px; border-radius: 10px; font: inherit; font-weight: 600; cursor: pointer; text-decoration: none; }
.app-share-primary { background: var(--green); color: #fff; border: 1px solid var(--green); }
.app-share-secondary { background: var(--surface); color: var(--green); border: 1px solid var(--border); }
.app-share-dialog button:disabled { opacity: .55; cursor: wait; }
.app-share-feedback { margin: 12px 0 0; }
.app-share-feedback:empty { display: none; }
.app-share-card-section { border-top: 1px solid var(--border); margin-top: 24px; padding-top: 20px; }
.app-share-card-section h3 { margin: 0 0 14px; font-size: 17px; }
.app-share-save-hint { font-size: 12px; margin: 12px 0; }
.app-share-preview { display: block; width: 100%; height: auto; background: var(--canvas); border: 1px solid var(--border); border-radius: 12px; }
.app-share-opening { font-size: 13px; line-height: 1.6; margin-top: 16px; }
.app-share-opening summary { cursor: pointer; font-weight: 650; }
.app-share-opening dl { margin: 12px 0; }
.app-share-opening dt { font-weight: 650; margin-top: 12px; }
.app-share-opening dd { margin: 4px 0 0; color: var(--muted); }
.app-share-alternative { display: block; margin-top: 4px; }
.app-share-opening a { overflow-wrap: anywhere; color: var(--green); }
@media (max-width: 360px) { .app-share-dialog { --share-padding: 18px; } }
"},{"path":"src/Settings.tsx","content":"import { navigate } from "./navigation";
import type { ReactNode } from "react";
import type { OfflineStatus } from "./offline-readiness";
import { Icon } from "./Icon";
import type { Locale } from "./types";
export function Settings({
  locale,
  shareAction,
  onLocale,
  onInstall,
  onAbout,
  online,
  installed,
  offlineStatus,
}: {
  locale: Locale;
  shareAction?: ReactNode;
  onLocale: (locale: Locale) => void;
  onInstall: () => void;
  onAbout: () => void;
  online: boolean;
  installed: boolean;
  offlineStatus: OfflineStatus;
}) {
  const en = locale === "en",
    s = (zh: string, english: string) => (en ? english : zh);
  return (
    <section
      className="settings-view"
      aria-label={s("应用设置", "App settings")}
    >
      <h2 className="section-label">{s("偏好设置", "Preferences")}</h2>
      <div className="settings-group native-list">
        <fieldset className="language-setting">
          <legend>{s("界面语言", "Interface language")}</legend>
          <div className="language-options">
            {(
              [
                ["zh", "中文"],
                ["en", "English"],
              ] as const
            ).map(([value, label]) => (
              <label key={value}>
                <input
                  type="radio"
                  name="language"
                  value={value}
                  checked={locale === value}
                  onChange={() => onLocale(value)}
                />
                <span>{label}</span>
              </label>
            ))}
          </div>
          <p>{s("复习与学习辅助提示词的解释语言会跟随界面语言，英语练习内容保持英文。", "Review and learning helper explanations follow your interface language; English practice content stays in English.")}</p>
        </fieldset>
      </div>
      <h2 className="section-label">
        {s("使用 TalkSprout", "Using TalkSprout")}
      </h2>
      <div className="settings-group native-list">
        <button
          id="install"
          className="settings-row"
          onClick={(event) => {
            event.currentTarget.focus({ preventScroll: true });
            onInstall();
          }}
        >
          <span className="entry-icon">
            <Icon name="download" />
          </span>
          <span className="row-text">
            <strong>
              {installed
                ? s("已添加到主屏幕", "Added to Home Screen")
                : s("安装到手机", "Install app")}
            </strong>
            <small>
              {s(
                "像 App 一样，随时打开",
                "Open it like an app, whenever you need",
              )}
            </small>
          </span>
          <Icon name="chevron" />
        </button>
        {shareAction}
        <button
          id="about"
          className="settings-row"
          onClick={(event) => {
            event.currentTarget.focus({ preventScroll: true });
            onAbout();
          }}
        >
          <span className="entry-icon">
            <Icon name="help" />
          </span>
          <span className="row-text">
            <strong>{s("使用说明", "Instructions")}</strong>
            <small>
              {s(
                "开场练习、语音提示与结束复习",
                "Starting practice, spoken prompts, and reviews",
              )}
            </small>
          </span>
          <Icon name="chevron" />
        </button>
      </div>
      <div className="settings-group native-list">
        <button id="ai-entry" type="button" className="settings-row" onClick={()=>navigate("#ai", {talksproutAiOrigin: true})}>
          <span className="entry-icon"><Icon name="chat" /></span>
          <span className="row-text"><strong>{s("在 AI 里直接用 TalkSprout","Use TalkSprout directly in your AI")}</strong><small>{s("Skill · 插件 · MCP","Skill · Plugins · MCP")}</small></span>
          <Icon name="chevron" />
        </button>
      </div>
      <h2 className="section-label">{s("本机与离线", "On this device")}</h2>
      <div className="settings-group settings-notes">
        <div>
          <strong>
            {online
              ? s("当前在线", "Currently online")
              : s("当前离线", "Currently offline")}
          </strong>
          <p>
            {offlineStatus === "ready"
              ? s("离线内容已就绪，提示词可离线浏览和复制。外部 AI 仍需网络。", "Offline content is ready. Browse and copy prompts offline; your external AI still needs a connection.")
              : offlineStatus === "installing"
                ? s("正在准备离线内容，请保持页面打开并联网。", "Preparing offline content. Keep this page open and connected.")
                : offlineStatus === "unavailable"
                  ? s("此浏览器当前无法保存离线内容，请联网使用。", "This browser cannot currently save offline content. Use the app online.")
                  : s("尚未确认离线内容已就绪，请联网打开并等待准备完成。", "Offline readiness is not confirmed yet. Open the app online and allow preparation to finish.")}
          </p>
        </div>
        <div>
          <strong>
            {s("收藏只保存在本机", "Favorites stay on this device")}
          </strong>
