  await expect(page.getByRole("heading", { name: "没有找到这篇文章" })).toBeVisible();
});

test("dedicated configurations and global rules copy exactly with manual fallback", async ({ page }) => {
  await page.addInitScript(() => { Object.defineProperty(navigator, "clipboard", { value: { writeText: async (value: string) => { (window as unknown as { capturedPrompt: string }).capturedPrompt = value; } }, configurable: true }); });
  await page.goto("/#guides/ai-dedicated-companions");
  const blocks = page.locator(".guide-prompt");
  await expect(blocks).toHaveCount(5);
  for (const block of await blocks.all()) {
    const expected = await block.locator("textarea").inputValue();
    await block.getByRole("button", { name: "复制提示词", exact: true }).click();
    await expect(block.getByRole("status")).toContainText("已复制");
    expect(await page.evaluate(() => (window as unknown as { capturedPrompt: string }).capturedPrompt)).toBe(expected);
  }
  await page.goto("/#guides/ai-global-instructions");
  const strict = page.locator(".guide-prompt").filter({ hasText: "严格英语门槛" });
  await strict.getByRole("button", { name: "复制提示词", exact: true }).click();
  expect(await page.evaluate(() => (window as unknown as { capturedPrompt: string }).capturedPrompt)).toContain("Mock or scold the user in English in a sarcastic or teasing way.");
  await page.evaluate(() => { Object.defineProperty(navigator, "clipboard", { value: { writeText: async () => { throw new Error("denied"); } }, configurable: true }); });
  await strict.getByRole("button", { name: "复制提示词", exact: true }).click();
  await expect(strict.getByRole("status")).toContainText("手动复制");
  await expect(strict.locator("textarea")).toBeFocused();
  expect(await strict.locator("textarea").evaluate((el: HTMLTextAreaElement) => el.selectionEnd - el.selectionStart)).toBe((await strict.locator("textarea").inputValue()).length);
  await page.getByRole("button", { name: "English", exact: true }).click();
  await expect(page.locator(".guide-prompt").first().getByRole("button", { name: "Copy prompt", exact: true })).toBeVisible();
  await expect(page.locator(".guide-prompt").last().locator("textarea")).toHaveValue(/Always require the user to communicate primarily in English/);
});

test("pending guide copies cannot show stale feedback after leaving the article", async ({ page }) => {
  await page.addInitScript(() => { Object.defineProperty(navigator, "clipboard", { value: { writeText: () => new Promise<void>((_resolve, reject) => { (window as unknown as { failGuideCopy: () => void }).failGuideCopy = () => reject(new Error("late failure")); }) }, configurable: true }); });
  await page.goto("/#guides/ai-dedicated-companions");
  await page.locator(".guide-prompt").first().getByRole("button", { name: "复制提示词", exact: true }).click();
  await expect(page.locator(".guide-prompt button").first()).toBeDisabled();
  await page.getByRole("button", { name: "返回扩展资料", exact: true }).click();
  await page.evaluate(() => (window as unknown as { failGuideCopy: () => void }).failGuideCopy());
  await expect(page.getByRole("searchbox")).toBeVisible();
  await expect(page.getByText("自动复制不可用，请手动复制已选中的提示词。", { exact: true })).toHaveCount(0);
});
"},{"path":"tests/navigation.test.ts","content":"import { test } from "node:test";
import assert from "node:assert/strict";
import { readRoute } from "../src/navigation";
import { allPrompts } from "../src/prompts";

test("existing collection and review URLs retain their destination", () => {
  assert.deepEqual(readRoute("#collection/companions"), {
    page: "practice",
    collection: "companions",
    base: "#collection/companions",
    promptId: null,
    learningPromptId: null,
    infoId: null,
  });
  assert.equal(readRoute("#collection/materials").collection, "materials");
  assert.equal(readRoute("#collection/review").base, "#review");
  assert.equal(readRoute("#settings").page, "settings");
  assert.equal(readRoute("#unknown").base, "#library");
});
test("a prompt deep link opens only in the matching purpose", () => {
  for (const p of allPrompts) {
    const base = p.kind === "review" ? "#review" : "#library";
    assert.equal(readRoute(`${base}?prompt=${p.id}`).promptId, p.id);
    const wrong = p.kind === "review" ? "#library" : "#review";
    assert.equal(readRoute(`${wrong}?prompt=${p.id}`).promptId, null);
    assert.equal(readRoute(`#settings?prompt=${p.id}`).promptId, null);
  }
  assert.equal(readRoute("#review?prompt=missing").promptId, null);
});

test("settings sheets can be deep linked without leaking into practice routes", () => {
  assert.equal(readRoute("#settings?info=about").infoId, "about");
  assert.equal(readRoute("#settings?info=install").infoId, "install");
  assert.equal(readRoute("#library?info=about").infoId, null);
  assert.equal(readRoute("#settings?info=unknown").infoId, null);
});


test("supplementary links stay separate from coaches and reviews", () => {
  assert.equal(readRoute("#learning?prompt=writing-feedback").learningPromptId, "writing-feedback");
  assert.equal(readRoute("#learning?prompt=writing-feedback").promptId, null);
  for (const path of ["#library", "#review", "#settings", "#collection/materials"])
    assert.equal(readRoute(`${path}?prompt=writing-feedback`).learningPromptId, null);
  assert.equal(readRoute("#learning?prompt=daily-check-in").promptId, null);
  assert.equal(readRoute("#learning?prompt=missing").learningPromptId, null);
});

test("practice links restore compatible scenario without personal background", () => {
  const route = readRoute("#library?prompt=roleplay-coach&scene=technical-intro&pace=mock&format=spoken&background=secret");
  assert.deepEqual(route.sceneSelection, {sceneId:"technical-intro",pace:"mock",background:""});
  assert.equal(route.format, "spoken");
  assert.equal(readRoute("#library?prompt=daily-check-in&scene=technical-intro&pace=mock").sceneSelection?.pace, "coached");
  assert.equal(readRoute("#library?prompt=roleplay-coach&scene=missing").sceneSelection, undefined);
  assert.equal(readRoute("#settings?scene=technical-intro&format=spoken").format, undefined);
});
test("review options apply only to matching review prompts", () => {
  const review = allPrompts.find(p => p.kind === "review")!;
  const route = readRoute(`#review?prompt=${review.id}&source=transcript&format=spoken&scene=technical-intro`);
  assert.equal(route.reviewSource, "transcript");
  assert.equal(route.format, "spoken");
  assert.equal(route.sceneSelection, undefined);
  assert.equal(readRoute("#library?prompt=daily-check-in&source=transcript").reviewSource, undefined);
});

test("guide routes preserve article identity without opening prompt sheets", () => {
  const route = readRoute("#guides/ten-minute-ai-conversation?prompt=daily-check-in&scene=technical-intro");
  assert.equal(route.page, "guides");
  assert.equal(route.base, "#guides/ten-minute-ai-conversation");
  assert.equal((route as typeof route & { guideId?: string }).guideId, "ten-minute-ai-conversation");
  assert.equal(route.promptId, null);
  assert.equal(route.learningPromptId, null);
  assert.equal(route.sceneSelection, undefined);
  assert.equal(readRoute("#guides").page, "guides");
  assert.equal(readRoute("#guides/not-a-guide").page, "guides");
  assert.equal(readRoute("#guides-extra").page, "practice");
});

test("further resources retain a separate directory route without prompt parameters", () => {
  const route = readRoute("#guides?section=reading&prompt=daily-check-in");
  assert.equal(route.page, "guides");
  assert.equal(route.base, "#guides?section=reading");
  assert.equal(route.promptId, null);
  assert.equal(route.guideId, undefined);
  assert.equal(readRoute("#guides?section=unknown").base, "#guides");
});


test("companion and resource article identities remain distinct", () => {
  for (const id of ["four-strands-of-language-learning", "build-a-learning-routine", "self-talk-to-real-conversation", "ten-minute-ai-conversation", "english-resource-directory", "choose-learning-materials"])
    assert.equal(readRoute(`#guides/${id}`).guideId, id);
});
test('AI installation has an independent route and cannot open practice prompts',()=>{
 const route=readRoute('#ai?prompt=roleplay-coach');
 assert.equal(route.page,'ai');assert.equal(route.base,'#ai');assert.equal(route.promptId,null);
});
"},{"path":"tests/sharing.spec.ts","content":"import { test, expect, type Page } from "@playwright/test";
import { PNG } from "pngjs";
import AxeBuilder from "@axe-core/playwright";
import jsQR from "jsqr";
import { readFile } from "node:fs/promises";

async function openShare(page: Page, settings = false) {
  await page.getByRole("button", { name: settings ? "分享 TalkSprout" : "分享应用", exact: true }).click();
  return page.getByRole("dialog", { name: "分享 TalkSprout" });
}

test("share hub copies the deployment home without route or private query", async ({ page }) => {
  await page.addInitScript(() => Object.defineProperty(navigator, "clipboard", { configurable: true, value: { writeText: async (text: string) => { (window as unknown as { copied: string }).copied = text; } } }));
  await page.goto("/?private=PRIVATE_468#settings");
  const dialog = await openShare(page, true);
  await dialog.getByRole("button", { name: "复制应用链接", exact: true }).click();
  expect(await page.evaluate(() => (window as unknown as { copied: string }).copied)).toBe("http://127.0.0.1:4173/");
  await expect(dialog.getByRole("status").filter({ hasText: "应用链接已复制" })).toBeVisible();
});

test("native link sharing and cancellation keep the card available", async ({ page }) => {
  await page.addInitScript(() => Object.defineProperty(navigator, "share", { configurable: true, value: async (data: ShareData) => {
    (window as unknown as { shared: ShareData }).shared = data;
    throw new DOMException("Cancelled", "AbortError");
  } }));
  await page.goto("/#guides");
  const dialog = await openShare(page);
  await dialog.getByRole("button", { name: "分享应用链接", exact: true }).click();
  expect(await page.evaluate(() => (window as unknown as { shared: ShareData }).shared)).toMatchObject({ title: "TalkSprout 开口芽", url: "http://127.0.0.1:4173/" });
  await expect(dialog).toBeVisible();
  await expect(dialog.getByRole("status").filter({ hasText: /失败/ })).toHaveCount(0);
  await expect(dialog.getByRole("img", { name: /二维码分享卡片/ })).toBeVisible();
});

test("denied clipboard selects the clean link and dismissal restores focus", async ({ page }) => {
  await page.addInitScript(() => Object.defineProperty(navigator, "clipboard", { configurable: true, value: { writeText: async () => { throw new Error("denied"); } } }));
  await page.goto("/#settings");
  const dialog = await openShare(page, true);
  await dialog.getByRole("button", { name: "复制应用链接", exact: true }).click();
  await expect(dialog.getByRole("textbox")).toHaveValue("http://127.0.0.1:4173/");
  await expect(dialog.getByRole("textbox")).toBeFocused();
  await expect(dialog.getByRole("status").filter({ hasText: "手动复制" })).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(dialog).not.toBeVisible();
  await expect(page.getByRole("button", { name: "分享 TalkSprout", exact: true })).toBeFocused();
});

test("downloaded PNG decodes to the app home and share dialog provides iPhone opening instructions", async ({ page }) => {
  await page.goto("/?private=PRIVATE_468#settings");
  const dialog = await openShare(page, true);
  const preview = dialog.getByRole("img", { name: /二维码分享卡片/ });
  await expect(preview).toBeVisible();
  await expect(dialog.getByText("二维码在另一块屏幕上", { exact: true })).toBeVisible();
  await expect(dialog.getByText("图片就在这台 iPhone 上", { exact: true })).toBeVisible();
  const downloading = page.waitForEvent("download");
  await dialog.getByRole("link", { name: "下载分享卡片", exact: true }).click();
  const download = await downloading;
  expect(download.suggestedFilename()).toBe("talksprout-share-zh.png");
  const png = PNG.sync.read(await readFile((await download.path())!));
  expect(png.width).toBe(1080);
  // The central app badge must be present, not merely a decodable plain QR.
  let greenPixels = 0;
  for (let y = 450; y < 850; y++) for (let x = 490; x < 590; x++) {
    const i = (y * png.width + x) * 4;
    if (png.data[i + 1] > png.data[i] * 1.3 && png.data[i + 1] > png.data[i + 2]) greenPixels++;
  }
  expect(greenPixels).toBeGreaterThan(500);

  expect(png.height).toBeGreaterThan(1500);
  expect(jsQR(new Uint8ClampedArray(png.data), png.width, png.height)?.data).toBe("http://127.0.0.1:4173/");
  const reduced = await preview.evaluate(async (img: HTMLImageElement) => {
    await img.decode();
    const canvas = document.createElement("canvas");
    canvas.width = 360;
    canvas.height = Math.round(img.naturalHeight * 360 / img.naturalWidth);
    const context = canvas.getContext("2d")!;
    context.drawImage(img, 0, 0, canvas.width, canvas.height);
    return { width: canvas.width, height: canvas.height, data: Array.from(context.getImageData(0, 0, canvas.width, canvas.height).data) };
  });
  expect(jsQR(new Uint8ClampedArray(reduced.data), reduced.width, reduced.height)?.data).toBe("http://127.0.0.1:4173/");
  await download.saveAs("test-results/talksprout-share-zh.png");
});

test("file sharing sends a PNG and cancellation preserves download", async ({ page }) => {
  await page.addInitScript(() => {
    Object.defineProperty(navigator, "canShare", { configurable: true, value: (data: ShareData) => !!data.files?.length });
    Object.defineProperty(navigator, "share", { configurable: true, value: async (data: ShareData) => {
      const file = data.files![0];
      (window as unknown as { sharedFile: { name: string; type: string; size: number } }).sharedFile = { name: file.name, type: file.type, size: file.size };
      throw new DOMException("Cancelled", "AbortError");
    } });
  });
  await page.goto("/#library");
  const dialog = await openShare(page);
  await dialog.getByRole("button", { name: "分享卡片图片", exact: true }).click();
  expect(await page.evaluate(() => (window as unknown as { sharedFile: unknown }).sharedFile)).toMatchObject({ name: "talksprout-share-zh.png", type: "image/png" });
  await expect(dialog.getByRole("link", { name: "下载分享卡片", exact: true })).toBeVisible();
  await expect(dialog.getByRole("status").filter({ hasText: /失败/ })).toHaveCount(0);
});

test("English card and download remain available offline on a narrow screen", async ({ page, context }) => {
  await page.setViewportSize({ width: 320, height: 640 });
  await page.addInitScript(() => localStorage.setItem("talksprout:locale", "en"));
  await page.goto("/#settings");
  await expect(page.getByText("Offline content is ready.", { exact: false })).toBeVisible({ timeout: 30000 });
  await context.setOffline(true);
  await page.reload();
  await page.getByRole("button", { name: "Share app", exact: true }).click();
  const dialog = page.getByRole("dialog", { name: "Share TalkSprout" });
  await expect(dialog.getByRole("img", { name: /QR sharing card/ })).toBeVisible();
  expect(await dialog.evaluate(el => el.scrollWidth <= el.clientWidth)).toBe(true);
  await expect(dialog.getByText("On another screen", { exact: true })).toBeVisible();
  const downloading = page.waitForEvent("download");
  await dialog.getByRole("link", { name: "Download share card", exact: true }).click();
  const download = await downloading;
  expect(download.suggestedFilename()).toBe("talksprout-share-en.png");
  await download.saveAs("test-results/talksprout-share-en.png");
  await page.screenshot({ path: "test-results/share-card-mobile.png" });
});

test("card export failure offers retry while link copying stays usable", async ({ page }) => {
  await page.addInitScript(() => {
    const original = HTMLCanvasElement.prototype.toBlob;
    (window as unknown as { restorePng: () => void }).restorePng = () => { HTMLCanvasElement.prototype.toBlob = original; };
    HTMLCanvasElement.prototype.toBlob = function (callback) { callback(null); };
    Object.defineProperty(navigator, "clipboard", { configurable: true, value: { writeText: async () => {} } });
  });
  await page.goto("/#library");
  const dialog = await openShare(page);
  await expect(dialog.getByText("卡片暂未生成，你仍可复制链接分享。", { exact: true })).toBeVisible();
  await dialog.getByRole("button", { name: "复制应用链接", exact: true }).click();
  await expect(dialog.getByRole("status").filter({ hasText: "应用链接已复制" })).toBeVisible();
  await page.evaluate(() => (window as unknown as { restorePng: () => void }).restorePng());
  await dialog.getByRole("button", { name: "重新生成卡片", exact: true }).click();
  await expect(dialog.getByRole("img", { name: /二维码分享卡片/ })).toBeVisible();
});

test("failed image sharing keeps the download and preview available", async ({ page }) => {
  await page.addInitScript(() => {
    Object.defineProperty(navigator, "canShare", { configurable: true, value: () => true });
    Object.defineProperty(navigator, "share", { configurable: true, value: async () => { throw new DOMException("denied", "NotAllowedError"); } });
  });
  await page.goto("/#library");
  const dialog = await openShare(page);
  await dialog.getByRole("button", { name: "分享卡片图片", exact: true }).click();
  await expect(dialog.getByRole("status").filter({ hasText: "图片未能分享" })).toBeVisible();
  await expect(dialog.getByRole("link", { name: "下载分享卡片", exact: true })).toBeVisible();
  await expect(dialog.getByRole("img", { name: /二维码分享卡片/ })).toBeVisible();
});

test("closing releases the generated image and navigation dismisses the share hub", async ({ page }) => {
  await page.goto("/#library");
  const dialog = await openShare(page);
  const preview = dialog.getByRole("img", { name: /二维码分享卡片/ });
  await expect(preview).toBeVisible();
  const src = (await preview.getAttribute("src"))!;
  await dialog.getByRole("button", { name: "关闭", exact: true }).click();
  expect(await page.evaluate(async url => { try { await fetch(url); return false; } catch { return true; } }, src)).toBe(true);
  await openShare(page);
  await page.evaluate(() => { location.hash = "#settings"; });
  await expect(page.getByRole("dialog")).not.toBeVisible();
  await expect(page.getByRole("button", { name: "分享 TalkSprout", exact: true })).toBeVisible();
});


test("share hub is accessible and its close control stays visible while scrolling", async ({ page }) => {
  await page.setViewportSize({ width: 320, height: 640 });
  await page.goto("/#library");
  const dialog = await openShare(page);
  await expect(dialog.getByRole("img", { name: /二维码分享卡片/ })).toBeVisible();
  const results = await new AxeBuilder({ page }).include(".app-share-dialog").withTags(["wcag2a", "wcag2aa", "wcag21aa"]).analyze();
  expect(results.violations).toEqual([]);
  await dialog.evaluate(element => { element.scrollTop = element.scrollHeight; });
  await expect(dialog.getByRole("button", { name: "关闭", exact: true })).toBeInViewport();
  await dialog.getByRole("button", { name: "关闭", exact: true }).click();
  await expect(page.getByRole("button", { name: "分享应用", exact: true })).toBeFocused();
});
